option.value:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --sage: #5f8a6e;
      --sage-light: #8ab89a;
      --sage-dark: #3d6b52;
      --teal: #4a7c82;
      --teal-light: #7ab3b9;
      --cream: #f7f5f0;
      --white: #ffffff;
      --ink: #1e2d26;
      --ink-soft: #4a5e52;
      --ink-muted: #8a9e92;
      --border: rgba(95,138,110,0.18);
      --shadow-card: 0 8px 48px rgba(31,55,38,0.10), 0 2px 12px rgba(31,55,38,0.06);
      --shadow-btn: 0 4px 20px rgba(61,107,82,0.35);
    }

    html, body {
      height: 100%;
      font-family: 'DM Sans', sans-serif;
      background: var(--cream);
      color: var(--ink);
      overflow: hidden;
    }

    /* ─── Background global ─── */
    .bg-canvas {
      position: fixed; inset: 0; z-index: 0;
      background:
        radial-gradient(ellipse 70% 60% at 15% 20%, rgba(138,184,154,0.22) 0%, transparent 70%),
        radial-gradient(ellipse 55% 45% at 85% 75%, rgba(74,124,130,0.18) 0%, transparent 65%),
        radial-gradient(ellipse 40% 50% at 60% 10%, rgba(95,138,110,0.10) 0%, transparent 60%),
        radial-gradient(ellipse 80% 80% at 50% 50%, rgba(247,245,240,0.95) 0%, var(--cream) 80%);
    }

    /* ─── Controles de Presentación (Flotando abajo) ─── */
    .ppt-controls {
      position: fixed;
      bottom: 80px;
      left: 50%;
      transform: translateX(-50%);
      background: rgba(30, 45, 38, 0.85);
      backdrop-filter: blur(12px);
      padding: 8px 20px;
      border-radius: 99px;
      display: flex; gap: 16px; align-items: center; z-index: 9999;
      box-shadow: 0 10px 30px rgba(0,0,0,0.2); color: white;
    }
    .ppt-controls button {
      background: none; border: none; color: white; cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      padding: 4px; border-radius: 50%; transition: background 0.2s;
    }
    .ppt-controls button:hover { background: rgba(255,255,255,0.2); }
    .ppt-indicator { font-size: 13px; font-weight: 500; letter-spacing: 0.5px; opacity: 0.9; }

    /* ─── Lógica de Slides ─── */
    .slide {
      position: absolute; top: 0; left: 0; width: 100vw; height: 100vh;
      opacity: 0; pointer-events: none; z-index: 1;
      transform: scale(0.98);
      transition: opacity 0.5s ease, transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
      display: flex; flex-direction: column;
    }
    .slide.active { opacity: 1; pointer-events: auto; z-index: 10; transform: scale(1); }

    /* =========================================
       COMPONENTES COMPARTIDOS (App Interna)
       ========================================= */
    .app-header {
      height: 70px; display: flex; align-items: center; justify-content: space-between;
      padding: 0 40px; background: rgba(255,255,255,0.8); backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--border); flex-shrink: 0;
    }
    .app-content {
      flex: 1; overflow-y: auto; padding: 40px;
      display: flex; flex-direction: column; align-items: center;
    }
    .app-bottom-bar {
      height: 60px; background: rgba(247,245,240,0.9); backdrop-filter: blur(10px);
      border-top: 1px solid var(--border); display: flex; justify-content: center; gap: 40px; align-items: center;
      flex-shrink: 0; padding: 0 40px;
    }
    .bottom-tab {
      display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 500;
      color: var(--ink-soft); text-decoration: none; padding: 8px 12px; border-radius: 8px;
      transition: background 0.2s; cursor: pointer;
    }
    .bottom-tab:hover, .bottom-tab.active { background: rgba(95,138,110,0.1); color: var(--sage-dark); }
    .bottom-tab svg { width: 18px; height: 18px; }

    /* Títulos de sección internos */
    .section-title { font-family: 'DM Serif Display', serif; font-size: 32px; color: var(--ink); margin-bottom: 8px; text-align: center; }
    .section-subtitle { font-size: 15px; color: var(--ink-muted); margin-bottom: 32px; text-align: center; }

    /* ─── Navegación Superior Compartida ─── */
    .nav-logo { display: flex; align-items: center; gap: 12px; text-decoration: none; cursor: pointer; }
    .nav-logo-icon {
      width: 40px; height: 40px; border-radius: 10px; background: linear-gradient(135deg, var(--sage) 0%, var(--teal) 100%);
      display: flex; align-items: center; justify-content: center; color: white;
    }
    .nav-logo-text { display: flex; flex-direction: column; line-height: 1.1; }
    .nav-logo-text strong { font-family: 'DM Serif Display', serif; font-size: 24px; color: var(--ink); }
    .nav-logo-text span { font-size: 11px; color: var(--ink-muted); font-weight: 500; }

    .nav-links { display: flex; gap: 40px; list-style: none; position: absolute; left: 50%; transform: translateX(-50%); }
    .nav-links a { font-size: 15px; font-weight: 600; color: var(--ink-soft); text-decoration: none; position: relative; cursor: pointer; transition: color 0.2s; }
    .nav-links a:hover, .nav-links a.active { color: var(--teal); }
    .nav-links a.active::after { content: ''; position: absolute; bottom: -6px; left: 0; width: 100%; height: 2px; background: var(--teal); border-radius: 2px; }

    .nav-auth { display: flex; gap: 16px; align-items: center; }
    .btn-text { background: none; border: none; font-family: 'DM Sans'; font-size: 15px; font-weight: 600; color: var(--ink-soft); cursor: pointer; transition: color 0.2s; }
    .btn-text:hover { color: var(--teal); }
    .btn-outline { background: transparent; border: 1.5px solid var(--sage-light); border-radius: 99px; padding: 10px 24px; font-family: 'DM Sans'; font-size: 15px; font-weight: 600; color: var(--sage-dark); cursor: pointer; transition: all 0.2s; }
    .btn-outline:hover { background: rgba(138, 184, 154, 0.1); border-color: var(--sage); }

    .user-controls { display: flex; gap: 12px; align-items: center; }
    .user-controls .bell { width: 36px; height: 36px; border-radius: 50%; background: var(--cream); border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; cursor: pointer; transition: background 0.2s; }
    .user-controls .bell:hover { background: rgba(95,138,110,0.1); }
    .user-controls .avatar { width: 36px; height: 36px; border-radius: 50%; background: var(--sage); color: white; display: flex; align-items: center; justify-content: center; font-weight: bold; cursor: pointer; }

    /* =========================================
       SLIDE 0: LANDING PAGE
       ========================================= */
    .land-nav {
      position: absolute; top: 0; left: 0; right: 0; z-index: 100; height: 80px;
      display: flex; align-items: center; justify-content: space-between; padding: 0 6%;
      background: rgba(247, 245, 240, 0.6); backdrop-filter: blur(8px); border-bottom: 1px solid var(--border);
    }
    .hero { display: flex; height: 100vh; padding: 80px 6% 0; align-items: center; max-width: 1400px; margin: 0 auto; width: 100%; }
    .hero-left { flex: 0 0 45%; }
    .hero-left h1 { font-family: 'DM Serif Display', serif; font-size: 56px; line-height: 1.1; color: var(--ink); margin-bottom: 24px; }
    .hero-left h1 span { color: var(--teal); }
    .hero-left p { font-size: 18px; color: var(--ink-soft); margin-bottom: 40px; padding-left: 16px; border-left: 3px solid var(--sage-light); }

    .btn-primary-large {
      display: inline-flex; align-items: center; gap: 12px; padding: 16px 32px; border: none; border-radius: 99px;
      background: linear-gradient(135deg, var(--sage) 0%, var(--teal) 100%); color: white;
      font-family: 'DM Sans', sans-serif; font-size: 18px; font-weight: 600; cursor: pointer;
      box-shadow: 0 8px 30px rgba(61,107,82,0.3); transition: transform 0.2s;
    }
    .btn-primary-large:hover { transform: translateY(-2px); box-shadow: 0 12px 40px rgba(61,107,82,0.4); }

    .hero-right { flex: 1; display: flex; justify-content: flex-end; align-items: center; padding-right: 40px;}
    .orbit-container { position: relative; width: 500px; height: 500px; }
    .orbit-ring { position: absolute; inset: 20px; border: 1.5px dashed var(--sage-light); border-radius: 50%; opacity: 0.6; animation: spin 80s linear infinite; }
    @keyframes spin { 100% { transform: rotate(360deg); } }
    .center-building { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 150px; height: 150px; background: white; border-radius: 50%; box-shadow: 0 12px 40px rgba(31,55,38,0.12); display: flex; align-items: center; justify-content: center; z-index: 10; border: 1px solid var(--border); }
    .node { position: absolute; transform: translate(-50%, -50%); z-index: 5; display: flex; flex-direction: column; align-items: center; cursor: pointer; transition: transform 0.3s; }
    .node:hover { transform: translate(-50%, -50%) scale(1.1); z-index: 20; }
    .node-icon { width: 64px; height: 64px; border-radius: 50%; background: white; border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; font-size: 26px; box-shadow: 0 8px 24px rgba(31,55,38,0.08); margin-bottom: 8px; }
    .node span { font-size: 13px; font-weight: 600; color: var(--ink-soft); white-space: nowrap; background: rgba(247,245,240,0.9); padding: 4px 10px; border-radius: 12px; border: 1px solid var(--border); }

    /* =========================================
       SLIDE 1: AUTHENTICATION
       ========================================= */
    .center-layout { width: 100%; flex: 1; display: flex; align-items: center; justify-content: center; padding: 40px; }
    .card { width: 100%; max-width: 460px; background: var(--white); border-radius: 24px; box-shadow: var(--shadow-card); border: 1px solid var(--border); overflow: hidden; }
    .card-tabs { display: flex; border-bottom: 1px solid var(--border); background: rgba(247,245,240,0.5); }
    .tab { flex: 1; padding: 18px 0; font-size: 14px; font-weight: 600; text-align: center; cursor: pointer; color: var(--ink-muted); border: none; background: none; position: relative; }
    .tab.active { color: var(--sage-dark); background: var(--white); }
    .tab.active::after { content: ''; position: absolute; bottom: -1px; left: 24px; right: 24px; height: 2px; background: linear-gradient(90deg, var(--sage), var(--teal)); border-radius: 2px 2px 0 0; }
    .card-body { padding: 36px 40px 40px; }
    .card-heading { font-family: 'DM Serif Display', serif; font-size: 28px; color: var(--ink); margin-bottom: 6px; }
    .card-sub { font-size: 14px; color: var(--ink-muted); margin-bottom: 24px; }
    .field { margin-bottom: 16px; }
    .field label { display: block; font-size: 12px; font-weight: 600; color: var(--ink-soft); margin-bottom: 6px; }
    .input-wrap { position: relative; }
    .input-wrap input, .input-wrap select { width: 100%; height: 48px; padding: 0 14px; border: 1.5px solid var(--border); border-radius: 12px; background: rgba(247,245,240,0.5); font-family: 'DM Sans', sans-serif; font-size: 14px; outline: none; }
    .input-wrap input:focus, .input-wrap select:focus { border-color: var(--sage); background: var(--white); }
    .btn-primary { width: 100%; height: 52px; border: none; border-radius: 14px; background: linear-gradient(135deg, var(--sage) 0%, var(--teal) 100%); color: white; font-family: 'DM Sans'; font-size: 15px; font-weight: 600; cursor: pointer; box-shadow: var(--shadow-btn); display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px;}

    /* =========================================
       SLIDE 2: MAPA DE MÉXICO
       ========================================= */
    .map-container {
      position: relative; width: 100%; max-width: 1000px;
      aspect-ratio: 1024 / 650;
      background-color: #e8efe9;
      border-radius: 24px; border: 1px solid var(--border); box-shadow: var(--shadow-card);
      overflow: hidden;
      margin: 0 auto;
    }

    /* Imagen del mapa asegurada */
    .map-bg-img {
      position: absolute;
      top: 0; left: 0;
      width: 100%; height: 100%;
      object-fit: cover;
      opacity: 0.8;
      pointer-events: none;
      z-index: 1;
    }

    .map-pin {
      position: absolute; display: flex; align-items: center; gap: 12px;
      transform: translate(-18px, -18px); /* Centra el ícono en la coordenada (36px/2) */
      background: white; padding: 12px 16px; border-radius: 16px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.15); cursor: pointer;
      transition: transform 0.2s; border: 1px solid var(--border);
      z-index: 10;
    }
    .map-pin:hover { border-color: var(--sage); z-index: 20; }
    .pin-icon { width: 36px; height: 36px; background: var(--sage); border-radius: 50%; color: white; display: flex; align-items: center; justify-content: center; flex-shrink: 0; position: relative; }
    .pin-info h4 { font-size: 15px; color: var(--ink); margin-bottom: 2px; white-space: nowrap; }
    .pin-info p { font-size: 12px; color: var(--ink-muted); display: flex; align-items: center; gap: 4px; }

    /* =========================================
       SLIDE 3: BUILDING TYPE
       ========================================= */
    .building-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; width: 100%; max-width: 1100px; }
    .build-card { background: white; border: 1px solid var(--border); border-radius: 20px; overflow: hidden; cursor: pointer; transition: transform 0.2s; text-align: center; }
    .build-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-card); border-color: var(--sage); }
    .build-img { height: 160px; background: var(--cream); display: flex; align-items: center; justify-content: center; font-size: 64px; }
    .build-info { padding: 20px; }
    .build-info h4 { font-size: 16px; color: var(--ink); margin-bottom: 8px; }
    .build-info p { font-size: 13px; color: var(--ink-muted); }

    /* =========================================
       SLIDE 4: RESULTS
       ========================================= */
    .results-layout { display: flex; gap: 40px; width: 100%; max-width: 1200px; }
    .res-left { flex: 1; }
    .res-image { width: 100%; height: 300px; background: var(--cream); border-radius: 20px; border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; font-size: 80px; margin-bottom: 24px; }
    .res-right { flex: 1; background: white; border-radius: 20px; padding: 32px; border: 1px solid var(--border); box-shadow: var(--shadow-card); }

    .data-table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }
    .data-table th { text-align: left; padding: 12px 8px; font-size: 12px; color: var(--ink-muted); border-bottom: 1px solid var(--border); }
    .data-table td { padding: 16px 8px; font-size: 14px; color: var(--ink); border-bottom: 1px solid var(--cream); }
    .data-table tr:last-child td { border-bottom: none; }
    .highlight-green { color: var(--sage-dark); font-weight: 700; background: rgba(95,138,110,0.1); padding: 4px 8px; border-radius: 6px; }

    .savings-box { display: flex; gap: 16px; margin-bottom: 24px; }
    .save-item { flex: 1; background: var(--cream); padding: 16px; border-radius: 12px; text-align: center; border: 1px solid var(--border); }
    .save-item h5 { font-size: 24px; color: var(--sage-dark); margin-bottom: 4px; font-family: 'DM Serif Display', serif;}
    .save-item p { font-size: 12px; color: var(--ink-soft); }

    /* =========================================
       SLIDE 5: DASHBOARD / MIS PROYECTOS
       ========================================= */
    .dash-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; width: 100%; max-width: 900px; }
    .dash-card { background: white; border: 1px solid var(--border); border-radius: 16px; padding: 24px; display: flex; align-items: flex-start; gap: 16px; cursor: pointer; transition: transform 0.2s, box-shadow 0.2s; }
    .dash-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-card); }
    .dash-icon { width: 48px; height: 48px; border-radius: 12px; background: rgba(95,138,110,0.1); display: flex; align-items: center; justify-content: center; font-size: 24px; flex-shrink: 0; }
    .dash-text h3 { font-size: 18px; color: var(--ink); margin-bottom: 4px; }
    .dash-text p { font-size: 13px; color: var(--ink-muted); line-height: 1.4; }

    .brands-section { width: 100%; max-width: 900px; margin-top: 40px; background: white; border-radius: 16px; border: 1px solid var(--border); padding: 24px; }
    .brands-title { font-size: 14px; font-weight: 600; color: var(--ink-soft); margin-bottom: 16px; }
    .brands-list { display: flex; gap: 20px; align-items: center; }
    .brand-tag { padding: 6px 16px; border-radius: 99px; background: var(--cream); font-size: 13px; font-weight: 600; color: var(--ink); border: 1px solid var(--border); }

/* =========================================
   SLIDE 6: FAQ / AYUDA
   ========================================= */
.faq-container { width: 100%; max-width: 800px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.faq-item { background: white; border: 1px solid var(--border); border-radius: 16px; overflow: hidden; transition: all 0.3s; }
.faq-item:hover { border-color: var(--sage); box-shadow: 0 4px 12px rgba(95,138,110,0.08); }
.faq-question { width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 20px 24px; background: none; border: none; font-family: 'DM Sans', sans-serif; font-size: 15px; font-weight: 600; color: var(--ink); cursor: pointer; text-align: left; }
.faq-question:hover { color: var(--teal); }
.faq-icon { transition: transform 0.3s; color: var(--sage-dark); flex-shrink: 0; margin-left: 16px;}
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease; background: rgba(247,245,240,0.4); }
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p { padding: 0 24px 20px; font-size: 14px; color: var(--ink-soft); line-height: 1.6; }

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --sage: #2196F3;
      --sage-light: #64B5F6;
      --sage-dark: #0D47A1;
      --teal: #00796B;
      --teal-light: #4DB6AC;
      --cream: #ffffff;
      --white: #ffffff;
      --ink: #263238;
      --ink-soft: #455A64;
      --ink-muted: #78909C;
      --border: rgba(33,150,243,0.18);
      --shadow-card: 0 8px 48px rgba(13,71,161,0.05), 0 2px 12px rgba(13,71,161,0.03);
      --shadow-btn: 0 4px 20px rgba(13,71,161,0.25);
    }

